<?php echo '<div class="card table-wrap"><div class="card-head"><h3>Reconciliation Batch History</h3></div><table class="table"><tr><th>Date</th><th>File</th><th>Processed By</th><th></th></tr>';foreach($pdo->query(history_sql('SELECT b.*,u.name user_name FROM reconciliation_batches b LEFT JOIN users u ON u.id=b.user_id ORDER BY b.id DESC LIMIT 500')) as $r)echo '<tr><td>'.e($r['created_at']).'</td><td>'.e($r['filename']).'</td><td>'.e($r['user_name']).'</td><td><a class="btn ghost sm" href="?page=reconciliation_detail&id='.(int)$r['id'].'">View Details</a></td></tr>';echo '</table></div>';
